def compute(vars):
    depreciation_expenses = [vars["v1"], vars["v2"], vars["v3"]]
    largest = max(depreciation_expenses)
    smallest = min(depreciation_expenses)
    difference = largest - smallest

    return {
        "value": difference,
        "trace": {
            "depreciation_expenses": depreciation_expenses,
            "largest": largest,
            "smallest": smallest,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
